export function resolveLanguage(preferences) {
  for (const preference of preferences) {
    const code = String(preference || '').split('-')[0].toLowerCase();
    if (code === 'tl') return 'fil';
    if (Object.hasOwn(languages, code)) return code;
  }
  return 'en';
}

export function localized(code, source, values) {
  const column = columns.indexOf(code);
  const text = column < 0 ? source : messages[source]?.[column] ?? source;
  return values ? text.replace(/\{(\w+)\}/g, (token,key) => Object.hasOwn(values,key) ? values[key] : token) : text;
}
